// Command unicode writes go_unicode.rs: the tables of Go's unicode package that regexp/syntax
// reads (categories, scripts, their case-folding tables, category aliases and the simple case
// folding orbits), taken from the Go toolchain that runs it.
//
// From the repository root:
//
//	go run ./rust/crates/bidder-params/testdata/go/unicode rust/crates/bidder-params/src/gojsonschema/go_unicode.rs
//	rustfmt +nightly-2026-11-13 --edition 2024 rust/crates/bidder-params/src/gojsonschema/go_unicode.rs
package main

import (
	"bufio"
	"fmt"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

// group writes long decimal literals the way clippy wants them: digits grouped by three.
func group(digits string) string {
	if len(digits) <= 4 {
		return digits
	}
	var b strings.Builder
	for i, d := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteByte('_')
		}
		b.WriteRune(d)
	}
	return b.String()
}

func number(v int64) string {
	if v < 0 {
		return "-" + group(strconv.FormatInt(-v, 10))
	}
	return group(strconv.FormatInt(v, 10))
}

// flatten lists a table as lo, hi, stride triples, R16 before R32 like Go.
func flatten(t *unicode.RangeTable) []string {
	var out []string
	for _, r := range t.R16 {
		out = append(out, number(int64(r.Lo)), number(int64(r.Hi)), number(int64(r.Stride)))
	}
	for _, r := range t.R32 {
		out = append(out, number(int64(r.Lo)), number(int64(r.Hi)), number(int64(r.Stride)))
	}
	return out
}

func constName(prefix, name string) string {
	return prefix + strings.ToUpper(name)
}

func sortedKeys(m map[string]*unicode.RangeTable) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func lookupCaseRange(r rune) *unicode.CaseRange {
	ranges := unicode.CaseRanges
	i := sort.Search(len(ranges), func(i int) bool { return rune(ranges[i].Hi) >= r })
	if i < len(ranges) && rune(ranges[i].Lo) <= r {
		return &ranges[i]
	}
	return nil
}

func convertCase(c int, r rune, cr *unicode.CaseRange) rune {
	delta := cr.Delta[c]
	if delta > unicode.MaxRune {
		return rune(cr.Lo) + ((r-rune(cr.Lo))&^1 | rune(c&1))
	}
	return r + delta
}

// fallbackFold is unicode.SimpleFold without its asciiFold and caseOrbit tables; the Rust port
// computes the same from CASE_RANGES.
func fallbackFold(r rune) rune {
	if cr := lookupCaseRange(r); cr != nil {
		if l := convertCase(unicode.LowerCase, r, cr); l != r {
			return l
		}
		return convertCase(unicode.UpperCase, r, cr)
	}
	return r
}

type writer struct {
	*bufio.Writer
}

func (w writer) line(format string, args ...any) {
	fmt.Fprintf(w, format+"\n", args...)
}

func (w writer) table(name string, t *unicode.RangeTable) {
	w.line("const %s: Table = &[%s];", name, strings.Join(flatten(t), ", "))
}

// tables writes every table of m (and of its fold map) and the sorted lookup list.
func (w writer) tables(list, doc, prefix string, m, fold map[string]*unicode.RangeTable) {
	keys := sortedKeys(m)
	w.line("/// %s", doc)
	w.line("pub(super) const %s: &[(&str, Table, Table)] = &[", list)
	for _, k := range keys {
		f := "NONE"
		if fold[k] != nil {
			f = constName("FOLD_"+prefix, k)
		}
		w.line("(%q, %s, %s),", k, constName(prefix, k), f)
	}
	w.line("];")
	w.line("")
	for _, k := range keys {
		w.table(constName(prefix, k), m[k])
		if t := fold[k]; t != nil {
			w.table(constName("FOLD_"+prefix, k), t)
		}
	}
	w.line("")
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: unicode <go_unicode.rs>")
		os.Exit(2)
	}
	f, err := os.Create(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	w := writer{bufio.NewWriter(f)}
	w.line("//! Generated by `testdata/go/unicode` from %s (Unicode %s): the tables of Go's `unicode`", runtime.Version(), unicode.Version)
	w.line("//! package that `regexp/syntax` reads. Do not edit: rerun the generator, then rustfmt.")
	w.line("")
	w.line("/// Go: `unicode.Version`.")
	w.line("#[cfg(test)]")
	w.line("pub(super) const VERSION: &str = %q;", unicode.Version)
	w.line("")
	w.line("/// A Go `unicode.RangeTable` as `lo, hi, stride` triples (`R16`, then `R32`).")
	w.line("pub(super) type Table = &'static [u32];")
	w.line("")
	w.line("/// No fold table (Go: a nil `*unicode.RangeTable`).")
	w.line("const NONE: Table = &[];")
	w.line("")
	w.tables("CATEGORIES", "Go: `unicode.Categories` with `unicode.FoldCategory`, by name.", "GC_", unicode.Categories, unicode.FoldCategory)
	w.tables("SCRIPTS", "Go: `unicode.Scripts` with `unicode.FoldScript`, by name.", "SC_", unicode.Scripts, unicode.FoldScript)

	aliases := make([]string, 0, len(unicode.CategoryAliases))
	for k := range unicode.CategoryAliases {
		aliases = append(aliases, k)
	}
	sort.Strings(aliases)
	w.line("/// Go: `unicode.CategoryAliases`, by alias.")
	w.line("pub(super) const CATEGORY_ALIASES: &[(&str, &str)] = &[")
	for _, k := range aliases {
		w.line("(%q, %q),", k, unicode.CategoryAliases[k])
	}
	w.line("];")
	w.line("")

	w.line("/// Go: `unicode.CaseRanges` as `(lo, hi, [upper, lower, title] deltas)`; a delta of")
	w.line("/// `MAX_RUNE + 1` (Go: `UpperLower`) alternates upper and lower case.")
	w.line("pub(super) const CASE_RANGES: &[(u32, u32, [i32; 3])] = &[")
	for _, cr := range unicode.CaseRanges {
		w.line("(%s, %s, [%s, %s, %s]),", number(int64(cr.Lo)), number(int64(cr.Hi)),
			number(int64(cr.Delta[0])), number(int64(cr.Delta[1])), number(int64(cr.Delta[2])))
	}
	w.line("];")
	w.line("")

	w.line("/// The runes whose `unicode.SimpleFold` is not the one `CASE_RANGES` gives (Go's")
	w.line("/// `asciiFold` and `caseOrbit` tables), as `(rune, SimpleFold(rune))`.")
	w.line("pub(super) const CASE_ORBIT: &[(u32, u32)] = &[")
	// FNV-1a over SimpleFold of every rune, for the Rust test that checks the port.
	hash := uint64(14695981039346656037)
	for r := rune(0); r <= unicode.MaxRune; r++ {
		folded := unicode.SimpleFold(r)
		if folded != fallbackFold(r) {
			w.line("(%s, %s),", number(int64(r)), number(int64(folded)))
		}
		hash ^= uint64(folded)
		hash *= 1099511628211
	}
	w.line("];")
	w.line("")
	w.line("/// FNV-1a (64-bit, one step per rune) of `unicode.SimpleFold(r)` for every rune `r`.")
	w.line("#[cfg(test)]")
	w.line("pub(super) const SIMPLE_FOLD_HASH: u64 = %s;", group(strconv.FormatUint(hash, 10)))
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := f.Close(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
